class CountIntervals {
    map<int,int> mp;
    long long total = 0;
public:
    CountIntervals() {}
    void add(int L, int R) {
        long long added = (long long)R - L + 1;
        auto it = mp.upper_bound(L);
        if (it != mp.begin() && prev(it)->second >= L) --it;
        vector<int> keys;
        while (it != mp.end() && it->first <= R) {
            added -= (long long)min(it->second, R) - max(it->first, L) + 1;
            L = min(L, it->first);
            R = max(R, it->second);
            keys.push_back(it->first);
            ++it;
        }
        for (int k : keys) mp.erase(k);
        mp[L] = R;
        total += added;
    }
    int count() { return (int)total; }
};

