class CountIntervals {
    private TreeMap<Integer, Integer> map = new TreeMap<>();
    private long total = 0;
    public CountIntervals() {}
    public void add(int L, int R) {
        long added = (long) R - L + 1;
        Integer k = map.floorKey(L);
        if (k == null || map.get(k) < L) k = map.higherKey(L);
        List<Integer> keys = new ArrayList<>();
        while (k != null && k <= R) {
            int r = map.remove(k);
            added -= (long) Math.min(r, R) - Math.max(k, L) + 1;
            L = Math.min(L, k);
            R = Math.max(R, r);
            keys.add(k);
            k = map.higherKey(L);
        }
        map.put(L, R);
        total += added;
    }
    public int count() { return (int) total; }
}

