    let added = R - L + 1;
    const iv = this.iv;
    let lo = 0, hi = iv.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (iv[mid][1] < L) lo = mid + 1; else hi = mid;
    }
    let i = lo;
    while (i < iv.length && iv[i][0] <= R) {
        added -= Math.min(iv[i][1], R) - Math.max(iv[i][0], L) + 1;
        L = Math.min(L, iv[i][0]);
        R = Math.max(R, iv[i][1]);
        iv.splice(i, 1);
    }
    iv.splice(i, 0, [L, R]);
    this.total += added;
};
CountIntervals.prototype.count = function() {
    return this.total;
};

