class CountIntervals:
    def __init__(self):
        self.cov = [False]
        self.lc = [0]
        self.rc = [0]
    def _upd(self, n, l, r, a, b):
        if self.cov[n]:
            return
        if a <= l and r <= b:
            self.cov[n] = True
            return
        m = (l + r) // 2
        if a <= m:
            if self.lc[n] == 0:
                self.lc[n] = len(self.cov)
                self.cov.append(False); self.lc.append(0); self.rc.append(0)
            self._upd(self.lc[n], l, m, a, b)
        if b > m:
            if self.rc[n] == 0:
                self.rc[n] = len(self.cov)
                self.cov.append(False); self.lc.append(0); self.rc.append(0)
            self._upd(self.rc[n], m + 1, r, a, b)
        self.cov[n] = self.cov[self.lc[n]] and self.cov[self.rc[n]]
    def _cnt(self, n, l, r):
        if self.cov[n]:
            return r - l + 1
        res = 0
        m = (l + r) // 2
        if self.lc[n]:
            res += self._cnt(self.lc[n], l, m)
        if self.rc[n]:
            res += self._cnt(self.rc[n], m + 1, r)
        return res
    def add(self, left: int, right: int) -> None:
        self._upd(0, 1, 10 ** 9, left, right)
    def count(self) -> int:
        return self._cnt(0, 1, 10 ** 9)

