class CountIntervals {
    vector<char> cov{0};
    vector<int> lc{0}, rc{0};
    void upd(int n, int l, int r, int a, int b) {
        if (cov[n]) return;
        if (a <= l && r <= b) { cov[n] = 1; return; }
        int m = l + (r - l) / 2;
        if (a <= m) {
            if (!lc[n]) { lc[n] = cov.size(); cov.push_back(0); lc.push_back(0); rc.push_back(0); }
            upd(lc[n], l, m, a, b);
        }
        if (b > m) {
            if (!rc[n]) { rc[n] = cov.size(); cov.push_back(0); lc.push_back(0); rc.push_back(0); }
            upd(rc[n], m + 1, r, a, b);
        }
        cov[n] = cov[lc[n]] && cov[rc[n]];
    }
    long long cnt(int n, int l, int r) {
        if (cov[n]) return (long long) r - l + 1;
        long long res = 0;
        int m = l + (r - l) / 2;
        if (lc[n]) res += cnt(lc[n], l, m);
        if (rc[n]) res += cnt(rc[n], m + 1, r);
        return res;
    }
public:
    CountIntervals() {}
    void add(int left, int right) { upd(0, 1, 1000000000, left, right); }
    int count() { return (int) cnt(0, 1, 1000000000); }
};

