class CountIntervals {
    private List<Boolean> cov = new ArrayList<>(List.of(false));
    private List<Integer> lc = new ArrayList<>(List.of(0)), rc = new ArrayList<>(List.of(0));
    public CountIntervals() {}
    private void upd(int n, int l, int r, int a, int b) {
        if (cov.get(n)) return;
        if (a <= l && r <= b) { cov.set(n, true); return; }
        int m = l + (r - l) / 2;
        if (a <= m) {
            if (lc.get(n) == 0) {
                lc.set(n, cov.size());
                cov.add(false); lc.add(0); rc.add(0);
            }
            upd(lc.get(n), l, m, a, b);
        }
        if (b > m) {
            if (rc.get(n) == 0) {
                rc.set(n, cov.size());
                cov.add(false); lc.add(0); rc.add(0);
            }
            upd(rc.get(n), m + 1, r, a, b);
        }
        cov.set(n, cov.get(lc.get(n)) && cov.get(rc.get(n)));
    }
    private long cnt(int n, int l, int r) {
        if (cov.get(n)) return (long) r - l + 1;
        long res = 0;
        int m = l + (r - l) / 2;
        if (lc.get(n) != 0) res += cnt(lc.get(n), l, m);
        if (rc.get(n) != 0) res += cnt(rc.get(n), m + 1, r);
        return res;
    }
    public void add(int left, int right) { upd(0, 1, 1000000000, left, right); }
    public int count() { return (int) cnt(0, 1, 1000000000); }
}

